package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.regex.Pattern;
import java.util.regex.PatternSyntaxException;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;
import org.jsoup.parser.Parser;
import org.jsoup.parser.Tag;
import org.jsoup.select.Collector;
import org.jsoup.select.Elements;
import org.jsoup.select.Evaluator;
import org.jsoup.select.Selector;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class Element_previousElementSibling_TriageGen1Test {

    @Test
    public void testPreviousElementSibling_WithPreviousSibling() {
        // Setup: <div><p>1</p><p>2</p></div>
        Document doc = Parser.parseHtml("<div><p>1</p><p>2</p></div>");
        Element parent = doc.child(0);
        Element first = parent.child(0);
        Element second = parent.child(1);

        // Execute
        Element result = second.previousElementSibling();

        // Verify
        Assert.assertNotNull(result);
        Assert.assertEquals(first, result);
        Assert.assertEquals("p", result.tagName());
    }

    @Test
    public void testPreviousElementSibling_IsFirstChildReturnsNull() {
        // Setup: <div><p>1</p><p>2</p></div>
        Document doc = Parser.parseHtml("<div><p>1</p><p>2</p></div>");
        Element parent = doc.child(0);
        Element first = parent.child(0);

        // Execute
        Element result = first.previousElementSibling();

        // Verify
        Assert.assertNull(result);
    }

    @Test
    public void testPreviousElementSibling_SingleChildReturnsNull() {
        // Setup: <div><p>1</p></div>
        Document doc = Parser.parseHtml("<div><p>1</p></div>");
        Element parent = doc.child(0);
        Element first = parent.child(0);

        // Execute
        Element result = first.previousElementSibling();

        // Verify
        Assert.assertNull(result);
    }

    @Test
    public void testPreviousElementSibling_WithTextNodesIntervening() {
        // Setup: <div><p>1</p>Text<p>2</p></div>
        // Note: previousElementSibling should skip TextNodes and find the previous Element
        Document doc = Parser.parseHtml("<div><p>1</p>Text<p>2</p></div>");
        Element parent = doc.child(0);
        Element first = parent.child(0);
        Element second = parent.child(1);

        // Execute
        Element result = second.previousElementSibling();

        // Verify
        Assert.assertNotNull(result);
        Assert.assertEquals(first, result);
    }

    @Test(expected = NullPointerException.class)
    public void testPreviousElementSibling_NoParentThrowsException() {
        // Setup: An element not attached to a document
        Element detached = new Element(new org.jsoup.nodes.Tag("p"), "");

        // Execute
        detached.previousElementSibling();

        // Note: The implementation calls parent().children(). 
        // If parent() returns null, it will throw NullPointerException.
    }
}
